  ('lituk:S4.8-003','LIFE_IN_UK'::public.cefr_level,'reading','In which part of Europe is the UK located?',array['The north east','The south west','The north west','The south east']::text[],'C','Handbook ch. 4 (A modern, thriving society): The UK lies in north-western Europe.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-004','LIFE_IN_UK'::public.cefr_level,'reading','The longest distance on the UK mainland is between which two places?',array['John O''Groats and Land''s End','Cardiff and Inverness','Belfast and Brighton','Dover and Edinburgh']::text[],'A','Handbook ch. 4 (A modern, thriving society): The longest mainland journey runs from John O''Groats in northern Scotland to Land''s End in south-west England.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-005','LIFE_IN_UK'::public.cefr_level,'reading','About how far is it from John O''Groats to Land''s End?',array['About 870 miles (1,400 kilometres)','About 370 miles (600 kilometres)','About 1,270 miles (2,040 kilometres)','About 570 miles (920 kilometres)']::text[],'A','Handbook ch. 4 (A modern, thriving society): The distance between the two points is roughly 870 miles, or about 1,400 km.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-006','LIFE_IN_UK'::public.cefr_level,'reading','Where is John O''Groats?',array['In the south-west corner of England','On the west coast of Wales','On the north coast of Scotland','On the north-east coast of Northern Ireland']::text[],'C','Handbook ch. 4 (A modern, thriving society): John O''Groats lies on Scotland''s northern coast, while Land''s End is at England''s south-western tip.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-007','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Most people in the UK live in the countryside.',array['True','False']::text[],'B','Handbook ch. 4 (A modern, thriving society): Most people live in towns and cities, even though much of Britain remains countryside.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-008','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO are cities in Wales?',array['Swansea and Plymouth','Swansea and Newport','Bradford and Newport','Newport and Dundee']::text[],'B','Handbook ch. 4 (A modern, thriving society): The handbook lists Cardiff, Swansea and Newport as cities in Wales.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-009','LIFE_IN_UK'::public.cefr_level,'reading','Which of these cities is in Scotland?',array['Plymouth','Dundee','Bradford','Swansea']::text[],'B','Handbook ch. 4 (A modern, thriving society): Scottish cities include Edinburgh, Glasgow, Dundee and Aberdeen.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-010','LIFE_IN_UK'::public.cefr_level,'reading','Norwich, Plymouth and Southampton are cities in:',array['Scotland','Wales','Northern Ireland','England']::text[],'D','Handbook ch. 4 (A modern, thriving society): These three are among the English cities listed in the handbook.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-011','LIFE_IN_UK'::public.cefr_level,'reading','What is the capital city of the UK?',array['London','Manchester','Birmingham','Edinburgh']::text[],'A','Handbook ch. 4 (A modern, thriving society): London is the capital of the United Kingdom.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-012','LIFE_IN_UK'::public.cefr_level,'reading','How many pence are there in a pound?',array['100','10','12','240']::text[],'A','Handbook ch. 4 (A modern, thriving society): The pound sterling (£) is divided into 100 pence.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-013','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is NOT a UK coin?',array['£2','50p','25p','20p']::text[],'C','Handbook ch. 4 (A modern, thriving society): The coins listed go from 1p up to £2, and between 20p and 50p there is no 25p coin.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-014','LIFE_IN_UK'::public.cefr_level,'reading','Which of these values is a coin rather than a banknote?',array['£10','£20','£2','£5']::text[],'C','Handbook ch. 4 (A modern, thriving society): The £1 and £2 are coins, while notes start at £5.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-015','LIFE_IN_UK'::public.cefr_level,'reading','What is the highest-value banknote listed in the handbook?',array['£100','£20','£500','£50']::text[],'D','Handbook ch. 4 (A modern, thriving society): The handbook lists notes of £5, £10, £20 and £50.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-016','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Shops and businesses must accept banknotes issued in Scotland and Northern Ireland.',array['True','False']::text[],'B','Handbook ch. 4 (A modern, thriving society): Scottish and Northern Irish notes are valid across the UK, but businesses are not obliged to take them.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-017','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Welsh is taught in Welsh schools and universities.',array['True','False']::text[],'A','Handbook ch. 4 (A modern, thriving society): Welsh, a language entirely distinct from English, is spoken by many people in Wales and is part of teaching in its schools and universities.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-018','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what was the UK population in 1801?',array['8 million','4 million','20 million','40 million']::text[],'A','Handbook ch. 4 (A modern, thriving society): The handbook''s table gives the UK population in 1801 as 8 million.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-019','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what was the UK population in 1901?',array['40 million','8 million','57 million','20 million']::text[],'A','Handbook ch. 4 (A modern, thriving society): By 1901 the population had reached 40 million, according to the handbook''s table.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-020','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what was the UK population in 1951?',array['62 million','40 million','50 million','57 million']::text[],'C','Handbook ch. 4 (A modern, thriving society): The handbook records a population of 50 million in 1951.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-021','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what was the UK population in 2010?',array['Just under 50 million','Just over 70 million','Just over 62 million','Just over 57 million']::text[],'C','Handbook ch. 4 (A modern, thriving society): In 2010 the UK had a little more than 62 million people, according to the handbook''s table.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-022','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what was the population of the UK in 1600?',array['Just over 1 million','About 20 million','About 8 million','Just over 4 million']::text[],'D','Handbook ch. 4 (A modern, thriving society): The handbook''s table starts in 1600 with a population of a little more than 4 million.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-023','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO factors have played a part in UK population growth?',array['Wars and emigration','Migration and shorter life expectancy','Migration and longer life expectancy','Emigration and a falling birth rate']::text[],'C','Handbook ch. 4 (A modern, thriving society): Population growth has sped up recently, helped by migration and people living longer.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-024','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: UK population growth has been slower in recent years than in the past.',array['True','False']::text[],'B','Handbook ch. 4 (A modern, thriving society): Population growth has actually been faster in recent years.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-025','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, roughly what percentage of the UK population lives in England?',array['64%','74%','84%','94%']::text[],'C','Handbook ch. 4 (A modern, thriving society): England consistently holds about 84% of the UK''s people.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-026','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, roughly what percentage of the UK population lives in Wales?',array['Around 1%','Around 5%','Around 10%','Around 15%']::text[],'B','Handbook ch. 4 (A modern, thriving society): Wales accounts for about 5% of the UK population.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-027','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, roughly what percentage of the UK population lives in Scotland?',array['Just over 18%','Just over 8%','Just under 3%','About 25%']::text[],'B','Handbook ch. 4 (A modern, thriving society): Scotland has a little over 8% of the UK''s people.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-028','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, which part of the UK has less than 3% of the total population?',array['Scotland','Wales','England','Northern Ireland']::text[],'D','Handbook ch. 4 (A modern, thriving society): Northern Ireland makes up under 3% of the UK population, compared with about 5% for Wales and just over 8% for Scotland.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-029','LIFE_IN_UK'::public.cefr_level,'reading','There is now a record number of people in the UK aged:',array['85 and over','100 and over','65 and over','75 and over']::text[],'A','Handbook ch. 4 (A modern, thriving society): People are living longer, and the number aged 85 or older has reached a record level.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-030','LIFE_IN_UK'::public.cefr_level,'reading','Why are people in the UK living longer than ever before?',array['Improved living standards and better health care','A rise in the state pension age','Fewer people moving to the UK','Lower taxes and longer working hours']::text[],'A','Handbook ch. 4 (A modern, thriving society): Better living standards and improved health care mean people now live longer.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-031','LIFE_IN_UK'::public.cefr_level,'reading','An ageing population has an impact on the cost of:',array['university tuition fees','pensions and health care','military spending','building new schools']::text[],'B','Handbook ch. 4 (A modern, thriving society): With more very old people, the costs of pensions and health care are affected.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-032','LIFE_IN_UK'::public.cefr_level,'reading','In surveys, which is the most common ethnic description chosen in the UK?',array['White','Black','Mixed','Asian']::text[],'A','Handbook ch. 4 (A modern, thriving society): ''White'' is chosen most often; Asian, black and mixed groups are other significant groups.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-033','LIFE_IN_UK'::public.cefr_level,'reading','Where is the UK''s ethnic diversity changing especially rapidly?',array['On the Channel Islands','In small villages in the countryside','Only in the Scottish Highlands','In large cities such as London']::text[],'D','Handbook ch. 4 (A modern, thriving society): The population is diverse and changing fast, particularly in big cities like London.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-034','LIFE_IN_UK'::public.cefr_level,'reading','In UK surveys, the ''white'' ethnic description includes people of which descent?',array['Asian, black and mixed','European, Australian, Canadian, New Zealand and American','Only British-born people','Only people from Scotland and Ireland']::text[],'B','Handbook ch. 4 (A modern, thriving society): The ''white'' category is broad, covering people with European roots as well as those of Australian, Canadian, New Zealand and American origin.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-035','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: In the UK it is lawful to discriminate against a person because they are married or because they are not married.',array['True','False']::text[],'B','Handbook ch. 4 (A modern, thriving society): The law requires that men and women are not discriminated against because of their gender or marital status.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-036','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Married parents share equal responsibility for their children.',array['True','False']::text[],'A','Handbook ch. 4 (A modern, thriving society): When parents are married, mother and father have equal responsibility for their children.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-037','LIFE_IN_UK'::public.cefr_level,'reading','Roughly what share of the UK workforce is made up of women?',array['About three quarters','About a quarter','About half','About a third']::text[],'C','Handbook ch. 4 (A modern, thriving society): Women now account for around half of Britain''s workforce.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-038','LIFE_IN_UK'::public.cefr_level,'reading','Which statement about education in the UK is correct according to the handbook?',array['Women are not allowed to study some subjects','Boys usually leave school with better qualifications','More women than men study at university','Only men can study at the oldest universities']::text[],'C','Handbook ch. 4 (A modern, thriving society): On average girls get better school results than boys, and more women than men go to university.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-039','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: On average, girls in the UK leave school with better qualifications than boys.',array['True','False']::text[],'A','Handbook ch. 4 (A modern, thriving society): Girls tend to achieve better school qualifications than boys.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-040','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: In many UK families today, both partners work and share childcare and household chores.',array['True','False']::text[],'A','Handbook ch. 4 (A modern, thriving society): Women are no longer expected to stay at home; often both partners work and share responsibility for children and housework.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S4.8-041','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Men in the UK now work in a narrower range of jobs than they did in the past.',array['True','False']::text[],'B','Handbook ch. 4 (A modern, thriving society): As women''s job opportunities have grown, men have also moved into a wider variety of jobs.',array['life_in_uk','lituk_society']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-001','LIFE_IN_UK'::public.cefr_level,'reading','At the start of the 19th century, which people were able to vote in elections for MPs?',array['All men over 18, whether or not they owned property','Women over 30 who owned land','All men and women over 21','Men over 21 who owned a certain amount of property']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Early in the 1800s only a small group could vote: property-owning men aged over 21.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-002','LIFE_IN_UK'::public.cefr_level,'reading','In the handbook, what does the word ''franchise'' refer to?',array['The boundaries of a parliamentary constituency','How many people were entitled to vote','A tax that voters had to pay','The salary paid to Members of Parliament']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The franchise means how many people held the right to vote, and it grew during the 19th century.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-003','LIFE_IN_UK'::public.cefr_level,'reading','Which of these was one of the six changes the Chartists campaigned for?',array['Elections every five years','Secret ballots','Votes for women over 30','An elected House of Lords']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Secret ballots were among the six Chartist demands of the 1830s and 1840s.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-004','LIFE_IN_UK'::public.cefr_level,'reading','How often did the Chartists want elections to be held?',array['Every three years','Every year','Every five years','Every seven years']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Annual elections were one of the Chartists'' six demands.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-005','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Payment for MPs was one of the reforms demanded by the Chartists.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Chartists wanted MPs to be paid, alongside five other changes.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-006','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: When it took place, the Chartist campaign was generally regarded as a success.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): At the time the campaign was mostly seen as having failed, although most of its aims were adopted by 1918.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-007','LIFE_IN_UK'::public.cefr_level,'reading','By which year had most of the Chartists'' reforms been adopted?',array['1969','1867','1918','1832']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Most of the Chartist demands had become law by 1918.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-008','LIFE_IN_UK'::public.cefr_level,'reading','In which year was the voting age lowered to 18 for both men and women?',array['1918','1928','1945','1969']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The voting age was reduced from 21 to 18 in 1969.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-009','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO were among the Chartists'' demands?',array['Compulsory voting and elections every ten years','A vote for every man and the right of any man to stand as an MP','Votes for women and an elected House of Lords','Abolition of the monarchy and votes for women']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Chartists wanted every man to have the vote and any man to be able to become an MP, among other reforms.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.2-010','LIFE_IN_UK'::public.cefr_level,'reading','Which of these was another Chartist demand?',array['Equal treatment of all regions in the electoral system','An end to elections for the House of Commons','A written constitution for the whole UK','A parliament for Scotland']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Chartists wanted every region to be equal within the electoral system.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-001','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what is a constitution?',array['The rules for electing local councils','A list of the monarch''s private powers','A single Act of Parliament passed in 1689','The set of principles that governs how a country is run']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): A constitution is the set of principles for governing a country, including its institutions and how their power is checked.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-002','LIFE_IN_UK'::public.cefr_level,'reading','What is the main reason given for the British constitution being ''unwritten''?',array['The monarch has always refused to sign a written version','The UK has never had a revolution that permanently created a totally new system of government','The UK has only existed in its current form since 1945','The original written copy was destroyed in a fire']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Unlike some countries, the UK has had no revolution that led permanently to an entirely new system, so its institutions developed gradually.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-003','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO countries does the handbook contrast with the UK because they have had revolutions leading to new systems of government?',array['Russia and China','Spain and Portugal','America and France','Germany and Italy']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The handbook notes that, unlike America or France, the UK never had such a revolution.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-004','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Some people argue that an unwritten constitution gives more flexibility and better government.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Opinions differ: some want a single document, while others think an unwritten constitution is more flexible.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-005','LIFE_IN_UK'::public.cefr_level,'reading','Apart from institutions, which TWO things does the British constitution also include?',array['Party manifestos and opinion polls','Newspapers and broadcasts','Treaties and religious texts','Laws and conventions']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The constitution covers institutions and also laws and conventions.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-006','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is listed as one of the main parts of government in the UK?',array['The civil service','The Church of England','The Bank of England','The BBC']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The main constitutional institutions include the civil service, alongside the monarchy, Parliament, PM, cabinet, judiciary, police and local government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-008','LIFE_IN_UK'::public.cefr_level,'reading','What does it mean that the UK has a constitutional monarchy?',array['The monarch chooses which MPs sit in Parliament','The monarch makes all the laws personally','The monarch does not rule but appoints the government the people have chosen','The monarch is elected by Parliament every five years']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): In a constitutional monarchy the king or queen appoints the democratically chosen government rather than ruling.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-009','LIFE_IN_UK'::public.cefr_level,'reading','Whom does the monarch invite to become Prime Minister?',array['The Speaker of the House of Commons','The leader of the party with the most MPs, or of a coalition','The MP who has served the longest','The leader of the House of Lords']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The monarch asks the leader of the largest party (or of a coalition) to form a government as Prime Minister.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-010','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The monarch is head of state of the UK and of many Commonwealth countries.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Besides the UK, the monarch is head of state for many Commonwealth countries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-011','LIFE_IN_UK'::public.cefr_level,'reading','What does the monarch''s speech at the opening of each parliamentary session set out?',array['The results of the last General Election','The monarch''s personal views on current events','The government''s policies for the coming year','The spending plans of the royal household']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): At the State Opening the monarch reads a speech summarising the government''s plans for the year ahead.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-012','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Acts of Parliament are made in the Prime Minister''s name.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Acts of Parliament are made in the name of the monarch, not the Prime Minister.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-013','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the monarch''s roles in representing the UK to the world?',array['Chairing weekly cabinet meetings','Deciding sentences in criminal trials','Setting the rate of income tax','Receiving foreign ambassadors and high commissioners']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The monarch receives ambassadors and high commissioners, hosts visiting heads of state and makes state visits abroad.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-014','LIFE_IN_UK'::public.cefr_level,'reading','Why does the handbook say the monarch provides stability and continuity?',array['The monarch chooses all government ministers personally','The monarch can veto any election result','The monarch remains head of state while governments and Prime Ministers change','The monarch writes the budget each year']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Governments come and go, but the monarch continues as head of state.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-015','LIFE_IN_UK'::public.cefr_level,'reading','When is the national anthem played?',array['Only at international football matches','Only on the monarch''s official birthday','At important national occasions and events attended by the monarch or Royal Family','At the start of every school day']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The anthem is played at key national events and at events the King, Queen or Royal Family attend.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-016','LIFE_IN_UK'::public.cefr_level,'reading','How does the affirmation of allegiance differ from the oath of allegiance?',array['It does not swear by Almighty God','It is used only by people born in the Commonwealth','It promises loyalty to Parliament instead of the monarch','It must be spoken in Welsh']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The oath begins by swearing by Almighty God, while the affirmation is a solemn declaration without that religious wording.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-017','LIFE_IN_UK'::public.cefr_level,'reading','Together, all of the elected MPs make up which body?',array['The House of Lords','The civil service','The House of Commons','The cabinet']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Every MP elected at a General Election sits in the House of Commons.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-018','LIFE_IN_UK'::public.cefr_level,'reading','Which party usually forms the government?',array['The party with the oldest leader','The party with the majority of MPs','The party chosen by the monarch','The party with the most members of the House of Lords']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The party that has a majority of MPs forms the government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-019','LIFE_IN_UK'::public.cefr_level,'reading','Why is the House of Commons seen as the more important of the two Houses of Parliament?',array['Its members are democratically elected','Its members are appointed by the monarch','It meets in a larger building','It is the older of the two Houses']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Commons is regarded as more important because its members are chosen by voters.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-020','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Prime Minister and almost all cabinet members sit in the House of Lords.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The PM and nearly the whole cabinet are MPs in the House of Commons, not peers.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-021','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the responsibilities of an MP?',array['Collecting taxes from constituents','Appointing judges to the Crown Court','Scrutinising and commenting on what the government is doing','Running the local police force']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): MPs represent their constituency, help make laws, scrutinise the government and debate national issues.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-022','LIFE_IN_UK'::public.cefr_level,'reading','What are members of the House of Lords known as?',array['Magistrates','Councillors','Commissioners','Peers']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Members of the House of Lords are called peers.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-023','LIFE_IN_UK'::public.cefr_level,'reading','What is a ''hereditary'' peer?',array['A peer elected by the public','A peer who is also a bishop','A peer appointed for their lifetime only','A peer who inherited their title']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Hereditary peers are those whose title was inherited.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-024','LIFE_IN_UK'::public.cefr_level,'reading','Until 1958, which of these groups could be peers alongside hereditary peers and Church of England bishops?',array['Army generals','Trade union leaders','Senior judges','Elected councillors']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Before 1958 all peers were hereditary, senior judges or Church of England bishops.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-025','LIFE_IN_UK'::public.cefr_level,'reading','Who formally appoints life peers?',array['The monarch, acting on the Prime Minister''s advice','The Speaker, after a vote of MPs','The voters, at a General Election','The Archbishop of Canterbury']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Life peers are appointed by the monarch acting on the Prime Minister''s advice.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-026','LIFE_IN_UK'::public.cefr_level,'reading','Who can nominate non-party peers to the House of Lords?',array['The Lord Chief Justice','The Speaker of the House of Commons','The Electoral Commission','An independent Appointments Commission']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Non-party peers are nominated by an independent Appointments Commission.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-027','LIFE_IN_UK'::public.cefr_level,'reading','What changed for hereditary peers in 1999?',array['They gained the right to choose the Prime Minister','They no longer had an automatic right to sit in the Lords','They were allowed to sit for the first time','They were given seats in the House of Commons']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Since 1999 hereditary peers no longer automatically attend; a small number of them are elected by the others to sit.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-028','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Compared with the House of Commons, the House of Lords is usually less independent of the government.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): In fact the Lords is usually more independent of the government than the Commons.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-029','LIFE_IN_UK'::public.cefr_level,'reading','Which statement about the two Houses of Parliament is correct?',array['The Lords must approve every law before MPs debate it','Neither House can change a decision of the other','The Lords can overrule the Commons on any law','The Commons can overrule the Lords, but rarely does so']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The House of Commons has the power to overrule the Lords, though it seldom uses it.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-030','LIFE_IN_UK'::public.cefr_level,'reading','Besides suggesting amendments, what else can the House of Lords do?',array['Call a General Election','Propose new laws, which MPs then discuss','Appoint the Speaker of the House of Commons','Dismiss the Prime Minister']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Lords can propose new laws for MPs to discuss and holds the government to account.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-031','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Speaker still represents a constituency and deals with constituents'' problems.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Although neutral, the Speaker is an MP who represents a constituency like any other MP.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-032','LIFE_IN_UK'::public.cefr_level,'reading','What does the Speaker make sure the opposition receives?',array['The right to veto government laws','A larger budget than the government','Half of the seats in the cabinet','A guaranteed amount of time to debate issues it chooses']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Speaker ensures the rules are followed, including guaranteed debate time for the opposition.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-033','LIFE_IN_UK'::public.cefr_level,'reading','Who represents Parliament on ceremonial occasions?',array['The Chancellor of the Exchequer','The Speaker','The Leader of the Opposition','The Home Secretary']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): One of the Speaker''s duties is to represent Parliament at ceremonies.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-034','LIFE_IN_UK'::public.cefr_level,'reading','Under ''first past the post'', who is elected in each constituency?',array['The candidate who receives the most votes','The candidate with the longest party membership','Every candidate who gets over 10% of the votes','The candidate chosen by the party leader']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): In each constituency the candidate with the largest number of votes wins the seat.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.3-035','LIFE_IN_UK'::public.cefr_level,'reading','Where can you find contact details for your elected representatives?',array['Your bank','The Crown Court','Your local police station','Your local library and www.parliament.uk']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Contact details for representatives and their parties are available from local libraries and the Parliament website.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-001','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, Britain''s tradition of protecting individual rights has its roots in which TWO of these?',array['The Reform Act and the Education Act','The Treaty of Rome and the Act of Union','Magna Carta and the Bill of Rights of 1689','The Domesday Book and the Beveridge Report']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): British rights are traced back to Magna Carta, the Habeas Corpus Act and the 1689 Bill of Rights.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-002','LIFE_IN_UK'::public.cefr_level,'reading','Who played an important part in drafting the European Convention on Human Rights?',array['American generals','British diplomats and lawyers','Members of the Royal Family','French bishops']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): British diplomats and lawyers had a key role in writing the Convention.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-003','LIFE_IN_UK'::public.cefr_level,'reading','In which year did the UK sign the European Convention on Human Rights, as one of the first countries to do so?',array['1998','1950','1945','1957']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The UK was among the first signatories of the Convention in 1950.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-004','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the principles in the European Convention on Human Rights?',array['The right to a free house','The right to free university education','The right to a job for life','The right to a fair trial']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Convention includes the right to a fair trial, among other principles.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-005','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The European Convention on Human Rights prohibits slavery and forced labour.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Prohibition of slavery and forced labour is one of the Convention''s principles.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-006','LIFE_IN_UK'::public.cefr_level,'reading','Which of these freedoms is included in the European Convention on Human Rights?',array['Freedom to carry a weapon','Freedom to ignore jury service','Freedom of thought, conscience and religion','Freedom from paying taxes']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The Convention protects freedom of thought, conscience and religion, and freedom of expression.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-007','LIFE_IN_UK'::public.cefr_level,'reading','Under the Human Rights Act 1998, who must follow the principles of the European Convention on Human Rights?',array['The government, public bodies and the courts','Only private businesses','Only foreign visitors','Only the House of Lords']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Act requires the government, public bodies and courts to follow the Convention.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-008','LIFE_IN_UK'::public.cefr_level,'reading','UK law protects people from unfair treatment at work because of which of these?',array['Marital status','Their choice of football club','Their hobbies','Their taste in music']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The grounds covered include marital status, as well as age, disability, sex, race, religion or belief, sexuality, and pregnancy and maternity.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-009','LIFE_IN_UK'::public.cefr_level,'reading','In England and Wales, which organisation can give information if you face discrimination?',array['HM Revenue & Customs','The Driver and Vehicle Licensing Agency','The Independent Police Complaints Commission','The Equality and Human Rights Commission']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Equality and Human Rights Commission covers England and Wales.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-010','LIFE_IN_UK'::public.cefr_level,'reading','Which body deals with equality issues in Northern Ireland?',array['The Police Ombudsman','The Northern Ireland Office','The Electoral Office for Northern Ireland','The Equality Commission for Northern Ireland']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Northern Ireland has its own Equality Commission, and also a Human Rights Commission.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-011','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Someone who is violent towards their partner can be prosecuted only if the couple are married.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Violence towards a partner is a serious crime whether the couple are married or living together, and whether the abuser is a man or woman.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-012','LIFE_IN_UK'::public.cefr_level,'reading','What are the safe places where people escaping domestic violence can stay called?',array['Refuges or shelters','Embassies','Lodges','Hospices']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): In some areas there are refuges or shelters for people facing domestic violence.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-013','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The National Domestic Violence Freephone Helpline can only be called during office hours.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The freephone helpline runs 24 hours a day, so it can be called at any time.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-014','LIFE_IN_UK'::public.cefr_level,'reading','What other names are used for female genital mutilation (FGM)?',array['Branding or tattooing','Cutting or female circumcision','Piercing or scarring','Ritual bathing']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): FGM is also referred to as cutting or female circumcision.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-015','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: It is a crime to take a girl or woman out of the UK so that FGM can be carried out.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Both carrying out FGM and taking someone overseas for it are crimes.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-016','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Arranged marriages where both people agree to marry are acceptable in the UK.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Marriage requires full and free consent; arranged marriages with the agreement of both are acceptable.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-017','LIFE_IN_UK'::public.cefr_level,'reading','What makes a marriage a forced marriage?',array['The couple have different religions','The couple''s families arranged the introduction','The wedding takes place outside the UK','One or both people do not or cannot consent to it']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): A forced marriage is one in which one or both parties do not or cannot consent.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-018','LIFE_IN_UK'::public.cefr_level,'reading','In which year were Forced Marriage Protection Orders introduced in England, Wales and Northern Ireland?',array['2008','1998','2002','2013']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The orders came in during 2008 under the Forced Marriage (Civil Protection) Act 2007.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-019','LIFE_IN_UK'::public.cefr_level,'reading','When were Protection Orders similar to Forced Marriage Protection Orders introduced in Scotland?',array['June 2014','March 2007','November 2011','January 2008']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Scotland introduced similar orders in November 2011.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-020','LIFE_IN_UK'::public.cefr_level,'reading','What is the maximum prison sentence for breaching a Forced Marriage Protection Order?',array['Ten years','Six months','Two years','Five years']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Breaching an order is contempt of court and can lead to up to two years in prison.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-021','LIFE_IN_UK'::public.cefr_level,'reading','Who can apply for a Forced Marriage Protection Order?',array['Only a religious leader','A potential victim or someone acting for them','Only a police officer','Only a member of Parliament']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The potential victim, or a person acting on their behalf, may apply.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-022','LIFE_IN_UK'::public.cefr_level,'reading','What is money raised from income tax used for?',array['The monarch''s private estates','Political party election campaigns','Government services such as roads, education, police and the armed forces','Only the state retirement pension']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Income tax funds public services like roads, schools, the police and the armed forces.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-023','LIFE_IN_UK'::public.cefr_level,'reading','What is the system called in which employers deduct income tax from wages and pay it to HMRC?',array['Council tax','Self-assessment','Pay As You Earn (PAYE)','Value Added Tax']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Under PAYE the employer takes the right amount of tax from pay and sends it to HMRC.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-024','LIFE_IN_UK'::public.cefr_level,'reading','How do employees usually pay their National Insurance Contributions?',array['They pay them in cash at a post office','They pay them once a year through the council','Their employer deducts them from their pay','They do not pay any; only the self-employed do']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Employers deduct employees'' contributions from pay, while the self-employed pay their own.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-025','LIFE_IN_UK'::public.cefr_level,'reading','What may happen to someone who does not pay enough National Insurance Contributions?',array['They will lose the right to vote','They may lose entitlement to some contributory benefits, such as Jobseeker''s Allowance or the full state pension','They will be refused a driving licence','They must leave the UK']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Insufficient contributions can mean losing entitlement to contributory benefits.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-026','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Some low-earning workers, such as part-timers, may not qualify for statutory maternity pay.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Workers with low earnings, such as some part-time staff, may miss out on statutory payments like maternity pay.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-027','LIFE_IN_UK'::public.cefr_level,'reading','What is a National Insurance number?',array['A number needed to register a car','A number given to every voter','A passport reference number','A unique personal account number']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): It ensures that the tax and contributions you pay are recorded against your name.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-028','LIFE_IN_UK'::public.cefr_level,'reading','When are young people in the UK sent their National Insurance number?',array['Just before their 16th birthday','When they start primary school','When they first register to vote','On their 18th birthday']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Every young person receives a National Insurance number shortly before turning 16.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-029','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: You can start work in the UK before you have a National Insurance number.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): You can begin working without one, but you will need one if you work or are self-employed.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-030','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, which department should a person with permission to work telephone to arrange a National Insurance number?',array['The Driver and Vehicle Licensing Agency (DVLA)','The Department for Work and Pensions (DWP)','The Electoral Commission','The Department for Education']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The handbook says to phone the DWP, which explains the application process and documents needed.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-031','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: A National Insurance number on its own proves to an employer that you have the right to work in the UK.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): A National Insurance number by itself is not proof of the right to work.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-032','LIFE_IN_UK'::public.cefr_level,'reading','What is the minimum age to ride a moped in the UK?',array['18','14','17','16']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): You can ride a moped at 16, while cars and motorcycles require you to be 17.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-033','LIFE_IN_UK'::public.cefr_level,'reading','What is the first step towards driving, according to government guidelines in the handbook?',array['Taking the practical driving test','Buying a car and insuring it','Getting an MOT certificate','Applying for a provisional driving licence and finding an instructor']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Learners first get a provisional licence and an instructor, then pass theory and practical tests.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-034','LIFE_IN_UK'::public.cefr_level,'reading','The driving theory test is made up of a multiple choice test and which other part?',array['An eyesight test at a hospital','A test of vehicle repair skills','A hazard perception test','A written essay on the Highway Code']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The theory test has a multiple choice section and a hazard perception section.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-035','LIFE_IN_UK'::public.cefr_level,'reading','Up to what age can drivers use their licence before having to renew it every three years?',array['75','70','65','60']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): A licence lasts until the driver is 70, then is valid for three years at a time.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-036','LIFE_IN_UK'::public.cefr_level,'reading','In Northern Ireland, what must a newly qualified driver display for one year after passing the test?',array['An ''N'' plate, for new driver','A ''P'' plate, for probationary driver','An ''L'' plate, for learner driver','An ''R'' plate, for restricted driver']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Newly qualified drivers in Northern Ireland show an ''R'' plate for a year.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-037','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, for how long can someone use a driving licence from Brazil to drive in the UK?',array['Up to 3 months','Up to 6 months','As long as the licence is valid','Up to 12 months']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Licences from countries outside the listed European ones can be used for up to 12 months, after which a UK licence is needed.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-038','LIFE_IN_UK'::public.cefr_level,'reading','Where must a car or motorcycle of a UK resident be registered?',array['The Ministry of Defence','HM Revenue & Customs','The Driver and Vehicle Licensing Agency (DVLA)','The local police station']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Residents'' vehicles must be registered with the DVLA.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-039','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what did drivers display on the windscreen to show that road tax had been paid?',array['An MOT certificate','A parking permit','A driving licence','A tax disc']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The handbook says vehicle owners pay annual road tax and display a tax disc.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.4-040','LIFE_IN_UK'::public.cefr_level,'reading','What do the letters MOT in ''MOT test'' stand for?',array['Ministry of Transport','Ministry of Taxation','Mechanical Overhaul Test','Motor Operation Test']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The annual vehicle check is called the Ministry of Transport (MOT) test.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-001','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: According to the handbook, people who disregard the law should not expect to be granted permanent residence.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): All residents must obey the law; anyone who disregards it should not expect to be allowed to settle permanently.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-002','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: In the UK, the law applies differently to people depending on where they come from.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Everyone receives equal treatment under the law, whoever they are and wherever they come from.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-003','LIFE_IN_UK'::public.cefr_level,'reading','Who usually investigates crimes in the UK?',array['Magistrates and judges','The police, or another body such as a local council','Members of Parliament','Citizens Advice']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Crimes are normally investigated by the police or another authority, and then punished by the courts.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-004','LIFE_IN_UK'::public.cefr_level,'reading','What is civil law used for?',array['Settling disputes between individuals or groups','Electing members of Parliament','Collecting income tax','Punishing people who commit crimes']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Civil law deals with disputes between people or groups, while criminal law deals with crimes.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-005','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: It is legal to carry a knife in the UK if it is only for self-defence.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Carrying any weapon is a criminal offence, even for self-defence.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-006','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Buying or selling cannabis is legal in the UK.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Dealing in or buying drugs including cannabis, heroin, cocaine and ecstasy is against the law.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-007','LIFE_IN_UK'::public.cefr_level,'reading','What is a racial crime under UK law?',array['Joining a religious group','Moving to a different area of the UK','Refusing to learn a foreign language','Harassing, alarming or distressing a person because of their ethnic origin or religion']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Targeting someone with harassment, alarm or distress because of their religion or ethnic origin is a crime.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-008','LIFE_IN_UK'::public.cefr_level,'reading','What is the minimum age for buying tobacco products in the UK?',array['17','16','18','21']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Selling cigarettes, cigars or other tobacco to anyone under 18 is illegal.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-009','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: It is illegal to smoke tobacco in almost all enclosed public places in the UK.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Smoking is banned in almost all enclosed public places, and signs show where you cannot smoke.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-010','LIFE_IN_UK'::public.cefr_level,'reading','From what age may someone have an alcoholic drink with a meal in a restaurant or hotel?',array['14','17','18','16']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): There is an exception to the age-18 rule: those aged 16 and over may have an alcoholic drink with a meal in a restaurant or hotel.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-011','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: It is a criminal offence to buy alcohol for someone who is under 18.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Both selling alcohol to under-18s and buying it for them are criminal offences.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-012','LIFE_IN_UK'::public.cefr_level,'reading','What are areas where people are not allowed to drink alcohol in public called?',array['Temperance districts','Dry constituencies','Sober areas','Alcohol-free zones']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Some places have alcohol-free zones, and the police can confiscate alcohol.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-013','LIFE_IN_UK'::public.cefr_level,'reading','A dispute between a landlord and a tenant about repairs or eviction falls under which kind of law?',array['Church law','Criminal law','Military law','Civil law (housing law)']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Housing law, covering landlord and tenant disputes, is an example of civil law.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-014','LIFE_IN_UK'::public.cefr_level,'reading','Which area of civil law covers cases of unfair dismissal or disputes over wages?',array['Employment law','Consumer law','Housing law','Criminal law']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Employment law deals with wages, unfair dismissal and workplace discrimination.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-015','LIFE_IN_UK'::public.cefr_level,'reading','What does ''keeping the peace'' mean as a duty of the police?',array['Guarding the Royal Family','Preventing disturbances','Negotiating peace treaties abroad','Settling disputes between neighbours in court']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): One of the police''s jobs is to prevent disturbances, also called keeping the peace.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-016','LIFE_IN_UK'::public.cefr_level,'reading','Who heads each of the UK''s separate police forces?',array['A Police and Crime Commissioner','A Chief Constable','A local magistrate','The Home Secretary']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Police forces are organised separately, each headed by a Chief Constable.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-017','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Police forces in the UK are under the direct control of the government.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The separate police forces, each headed by a Chief Constable, are independent of the government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-018','LIFE_IN_UK'::public.cefr_level,'reading','When did the public first elect Police and Crime Commissioners in England and Wales?',array['May 2016','June 2005','November 2012','May 1997']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): PCCs were first elected in November 2012.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-019','LIFE_IN_UK'::public.cefr_level,'reading','Who appoints the Chief Constable of a police force in England and Wales?',array['The local council','The Prime Minister','The Police and Crime Commissioner','The Lord Chief Justice']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): PCCs set local priorities and budgets and appoint the Chief Constable.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-020','LIFE_IN_UK'::public.cefr_level,'reading','Which of these must police officers NOT do?',array['Patrol the streets','Arrest people suspected of crimes','Make a false statement','Attend crime scenes']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Officers must obey the law and must not misuse authority, lie, be rude or abusive, or discriminate on racial grounds.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-021','LIFE_IN_UK'::public.cefr_level,'reading','If you are arrested and taken to the police station, what happens?',array['You are automatically taken to court that day','You lose the right to speak to a lawyer','You must pay a fine before being released','An officer tells you why you were arrested and you can seek legal advice']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Arrested people are told the reason for their arrest and may get legal advice.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-022','LIFE_IN_UK'::public.cefr_level,'reading','Which independent body deals with complaints about the police in Northern Ireland?',array['The Northern Ireland Assembly','The Police Ombudsman for Northern Ireland','The Electoral Office for Northern Ireland','The Equality Commission for Northern Ireland']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Complaints in Northern Ireland can go to the Police Ombudsman.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-023','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, which independent body handles complaints about the police in England and Wales?',array['The Equality and Human Rights Commission','The Electoral Commission','The Independent Police Complaints Commission','The Crown Prosecution Service']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The handbook names the Independent Police Complaints Commission for England and Wales.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-024','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, what is the most serious terrorist threat facing the UK?',array['Pirates operating in the English Channel','Al Qa''ida, its affiliates and like-minded organisations','Organised football supporters','Groups opposed to the Commonwealth']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The handbook names Al Qa''ida and related groups as the most serious threat, alongside other threats such as Northern Ireland-related terrorism.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-025','LIFE_IN_UK'::public.cefr_level,'reading','How does the handbook define extremism?',array['Voting for a small political party','Belonging to a minority religion','Active or vocal opposition to fundamental British values','Any disagreement with government policy']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The handbook describes extremism as opposing fundamental British values, whether vocally or actively; it covers both religious and far-right forms.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-026','LIFE_IN_UK'::public.cefr_level,'reading','If you believe someone is trying to draw you into an extremist or terrorist cause, what should you do?',array['Ignore it and say nothing','Report it to your bank','Write to a newspaper','Tell your local police force']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): You should notify your local police force.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-027','LIFE_IN_UK'::public.cefr_level,'reading','What is the collective name for judges?',array['The constabulary','The magistracy','The cabinet','The judiciary']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Judges together are called the judiciary; they interpret the law and ensure fair trials.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-028','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The government can interfere with the way judges interpret the law and run trials.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Judges interpret the law and ensure fair trials, and the government cannot interfere.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-029','LIFE_IN_UK'::public.cefr_level,'reading','If judges agree that an action of the government is illegal, what must the government do?',array['Dismiss the judges involved','Hold a referendum on the judgment','Change its policies or ask Parliament to change the law','Ask the monarch to overturn the ruling']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The government must either alter its policies or ask Parliament for a change in the law.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-030','LIFE_IN_UK'::public.cefr_level,'reading','What can judges order if a public body is not respecting someone''s legal rights?',array['That the body changes its practices and/or pays compensation','That the body is sold to a private company','That the body''s staff are sent to prison','That a General Election is held']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Judges may require the body to change how it works and/or to pay compensation.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-031','LIFE_IN_UK'::public.cefr_level,'reading','In Northern Ireland, who hears cases in a Magistrates'' Court?',array['A paid, legally qualified District Judge or Deputy District Judge','Unpaid local volunteers with no legal training','A sheriff with a jury','A jury of 12 members of the public']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Unlike England, Wales and Scotland, Northern Ireland uses paid, legally qualified District Judges.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-032','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, where are serious criminal cases heard?',array['In a Sheriff Court, with a sheriff or a sheriff and jury','In a County Court','In a Crown Court with a judge and jury','In a Justice of the Peace Court']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Serious Scottish cases go to a Sheriff Court, and the most serious to the High Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-033','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, where are the most serious criminal cases, such as murder, heard?',array['At a High Court with a judge and jury','At a Justice of the Peace Court','At a Children''s Hearing','At the Court of Session']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The most serious Scottish cases are heard by a judge and jury at a High Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-034','LIFE_IN_UK'::public.cefr_level,'reading','How are members of a jury chosen?',array['By the local council from volunteers','At random from the local electoral register','By the defendant','By the judge from among local lawyers']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Jurors are members of the public picked at random from the electoral register.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-035','LIFE_IN_UK'::public.cefr_level,'reading','Which of these could make someone not eligible for jury service?',array['Owning a car','Being a parent','Working part-time','Having a criminal conviction']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Everyone summoned must serve unless ineligible, for example due to a criminal conviction, or excused for a good reason like ill health.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-036','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, which third verdict, besides ''guilty'' and ''not guilty'', is possible in Scotland?',array['Not certain','Not proven','Partly guilty','Case dismissed']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Scottish juries could also return a verdict of ''not proven''.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-037','LIFE_IN_UK'::public.cefr_level,'reading','If a jury finds a defendant guilty, who decides the penalty?',array['The jury','The victim','The judge','The police']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The jury decides the verdict and the judge then decides the penalty.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-038','LIFE_IN_UK'::public.cefr_level,'reading','Who normally hears a case in a Youth Court?',array['A sheriff and a jury of 15','A judge and a jury of 12','Members of Parliament','Up to three specially trained magistrates or a District Judge']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Youth Court cases are heard by up to three specially trained magistrates or a District Judge.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-039','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Members of the public are allowed to watch hearings in a Youth Court.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The public are not allowed in Youth Courts.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-040','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is true of cases in a Youth Court?',array['The accused young person''s name and photograph cannot be published by the media','The parents are not allowed to attend','The accused must be under 10','The case is always heard by a jury']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Media may not publish the name or photographs of the young person, and parents or carers are expected to attend.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-041','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, which system deals with young people who have committed offences?',array['The Children''s Hearings System','The small claims procedure','The Youth Court','Youth conferencing']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Scotland uses the Children''s Hearings System for young offenders.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-042','LIFE_IN_UK'::public.cefr_level,'reading','Which system does Northern Ireland use to consider how a child who has committed an offence should be dealt with?',array['The small claims procedure','A Sheriff Court','The Children''s Hearings System','Youth conferencing']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Northern Ireland has a youth conferencing system.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-043','LIFE_IN_UK'::public.cefr_level,'reading','In England and Wales, which courts deal with civil disputes such as divorce, personal injury and recovering money owed?',array['Crown Courts','Youth Courts','Magistrates'' Courts','County Courts']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Many kinds of civil dispute are handled by County Courts.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-044','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, which court deals with most of the civil matters handled by County Courts elsewhere?',array['The Youth Court','The Crown Court','The Sheriff Court','The Justice of the Peace Court']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Most such civil matters in Scotland go to the Sheriff Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-045','LIFE_IN_UK'::public.cefr_level,'reading','In Scotland, where are serious civil cases, such as large compensation claims, dealt with?',array['A Justice of the Peace Court','A County Court','The Court of Session in Edinburgh','The High Court in London']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Serious civil cases go to the High Court in England, Wales and Northern Ireland and to the Court of Session in Scotland.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-046','LIFE_IN_UK'::public.cefr_level,'reading','In England, Wales and Northern Ireland, where are serious civil cases dealt with?',array['The Court of Session','The High Court','The Youth Court','The Magistrates'' Court']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Serious civil cases, such as those claiming large compensation, go to the High Court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-047','LIFE_IN_UK'::public.cefr_level,'reading','In England and Wales, the small claims procedure is used for claims of less than what amount?',array['£5,000','£1,000','£50,000','£10,000']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): In England and Wales small claims are those under £10,000.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-048','LIFE_IN_UK'::public.cefr_level,'reading','Where is a small claims hearing held?',array['In a Crown Court in front of a jury','At a police station','In the House of Commons','In an ordinary room in front of a judge, with both sides sitting around a table']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The hearing is informal, before a judge in an ordinary room.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-049','LIFE_IN_UK'::public.cefr_level,'reading','How can a small claim be issued online?',array['Through Money Claims Online','Through HM Revenue & Customs','Through the electoral register','Through the DVLA website']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Small claims can be started online using Money Claims Online.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-050','LIFE_IN_UK'::public.cefr_level,'reading','What do solicitors do?',array['Investigate crimes for the police','Give legal advice, act for their clients and represent them in court','Decide verdicts in Crown Court trials','Make new laws in Parliament']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Solicitors are trained lawyers who advise clients, take action for them and represent them in court.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-051','LIFE_IN_UK'::public.cefr_level,'reading','What are solicitors'' charges usually based on?',array['A fixed fee set by Parliament','The number of witnesses','The client''s income','How much time they spend on a case']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Charges usually depend on time spent, so check the likely cost at the start.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.5-052','LIFE_IN_UK'::public.cefr_level,'reading','Which organisation in England and Wales can give you information about solicitors?',array['The DVLA','The Electoral Commission','The Law Society','HM Revenue & Customs']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The Law Society (and its Scottish and Northern Irish equivalents) and Citizens Advice can help you find a solicitor.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-001','LIFE_IN_UK'::public.cefr_level,'reading','Who is the Prime Minister?',array['The leader of the political party in power','The person chosen by the Speaker','The longest-serving member of the House of Lords','The head of the civil service']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The PM leads the governing party, appoints the cabinet and controls many public appointments.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-002','LIFE_IN_UK'::public.cefr_level,'reading','How can a Prime Minister be replaced between General Elections?',array['The monarch dismisses them after a cabinet complaint','The House of Lords votes to remove them','The Speaker calls a public vote','MPs in the governing party decide to change the leader, or the PM resigns']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): A PM can be changed by MPs in the governing party, or if they wish to resign.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-003','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: A Prime Minister usually resigns if their party loses a General Election.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): When the governing party loses a General Election, the PM normally resigns.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-004','LIFE_IN_UK'::public.cefr_level,'reading','About how many senior MPs does the Prime Minister appoint as ministers in charge of departments?',array['About 50','About 100','About 5','About 20']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The PM appoints around 20 senior MPs to head departments, forming the cabinet.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-005','LIFE_IN_UK'::public.cefr_level,'reading','How often does the cabinet usually meet?',array['Weekly','Monthly','Daily','Once a year']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The cabinet is a committee that normally meets every week to decide government policy.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-006','LIFE_IN_UK'::public.cefr_level,'reading','What are the ministers in charge of areas like health, education or defence called?',array['Shadow ministers','Ministers without Portfolio','Secretaries of State','Lord Lieutenants']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Ministers in charge of areas like education and health are called Secretaries of State.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-007','LIFE_IN_UK'::public.cefr_level,'reading','Besides cabinet ministers, which other ministers take charge of particular areas of a department''s work?',array['Ministers of State and Parliamentary Under-Secretaries of State','Lord Mayors and councillors','Magistrates and Justices of the Peace','Chief Constables and Police Commissioners']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Each department has further ministers: Ministers of State and Parliamentary Under-Secretaries of State.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-008','LIFE_IN_UK'::public.cefr_level,'reading','What is the role of the shadow cabinet?',array['To advise the monarch on royal duties','To run the government when the PM is abroad','To count the votes at General Elections','To challenge the government and propose different policies']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Shadow ministers, appointed by the leader of the opposition, challenge the government and suggest alternatives.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-009','LIFE_IN_UK'::public.cefr_level,'reading','What is the minimum age for standing for election as an MP?',array['25','21','16','18']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Anyone aged 18 or over can stand, though they are unlikely to win without a major party''s nomination.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-010','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO are named in the handbook as major political parties?',array['The Jacobites and the Covenanters','The Whigs and the Chartists','The Royalists and the Roundheads','The Conservative Party and the Labour Party']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The major parties named are the Conservatives, Labour, the Liberal Democrats and parties representing Scottish, Welsh or Northern Irish interests.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-011','LIFE_IN_UK'::public.cefr_level,'reading','How often do the main political parties hold policy-making conferences?',array['Every month','Every year','Every five years','Only before General Elections']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The main parties have branches in most constituencies and hold annual policy-making conferences.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-012','LIFE_IN_UK'::public.cefr_level,'reading','Which organisation represents the views of British business?',array['Greenpeace','The Confederation of British Industry (CBI)','Liberty','The Law Society']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The CBI is a representative pressure group for British business.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-013','LIFE_IN_UK'::public.cefr_level,'reading','Which pressure group is given in the handbook as an example of campaigning on human rights?',array['Liberty','Greenpeace','Age UK','The CBI']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Liberty is named as a human rights campaign group, and Greenpeace as an environmental one.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-014','LIFE_IN_UK'::public.cefr_level,'reading','Greenpeace is given as an example of a pressure group that campaigns on which issue?',array['Animal welfare in zoos','Human rights','The environment','British business']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Greenpeace campaigns on the environment.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-015','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the core values of the civil service?',array['Secrecy from ministers','Party loyalty','Impartiality','Profit-making']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The core values are integrity, honesty, objectivity and impartiality, including political neutrality.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-016','LIFE_IN_UK'::public.cefr_level,'reading','How are civil servants chosen?',array['By the monarch','By the governing party after each election','By a public vote','On merit, through an application process like other jobs']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Civil servants are selected on merit and are not political appointees.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-017','LIFE_IN_UK'::public.cefr_level,'reading','To whom are civil servants accountable?',array['The leader of the opposition','Local councillors','Ministers','The Speaker']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Civil servants support the government and are accountable to ministers.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-018','LIFE_IN_UK'::public.cefr_level,'reading','What are the democratically elected councils that govern towns, cities and rural areas often called?',array['Local authorities','Devolved administrations','Shadow cabinets','Police authorities']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Elected councils are often known as local authorities.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-019','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Some areas of the UK have both district and county councils with different functions.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Some areas have two tiers of council, while most large towns and cities have a single authority.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-020','LIFE_IN_UK'::public.cefr_level,'reading','How are local authorities funded?',array['Through central government funding and local taxes','By the European Parliament','Only by donations from residents','Only by fines collected by the police']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Councils are funded partly by central government and partly by local taxation.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-021','LIFE_IN_UK'::public.cefr_level,'reading','In many local authorities, what is the role of the mayor?',array['Judge in the local court','Member of the House of Lords','Ceremonial leader of the council','Head of the local police force']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Many councils appoint a mayor as ceremonial leader; in some towns an elected mayor leads the administration.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-022','LIFE_IN_UK'::public.cefr_level,'reading','How many local authorities does London have?',array['50','12','33','25']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): There are 33 local authorities in London, with policy across the capital coordinated by the Mayor of London and the Greater London Authority.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-023','LIFE_IN_UK'::public.cefr_level,'reading','Since which year have some powers been devolved from central government to Wales, Scotland and Northern Ireland?',array['1922','2007','1969','1997']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Devolution of some powers began in 1997.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-024','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO policy areas remain under the control of the central UK government?',array['Housing and agriculture','Planning and the environment','Foreign affairs and immigration','Education and health']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Defence, foreign affairs, immigration, taxation and social security stay with the UK government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-025','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Scotland, Wales and Northern Ireland''s devolved administrations each have a separate civil service.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Each devolved administration has a civil service of its own.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-026','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, how many members does the National Assembly for Wales have?',array['60','90','40','129']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The handbook gives 60 Assembly Members (AMs) for Wales.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-027','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, how often are elections held for the National Assembly for Wales?',array['Every three years','Every year','Every four years','Every ten years']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): According to the handbook, Welsh Assembly elections were held every four years under a type of proportional representation.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-028','LIFE_IN_UK'::public.cefr_level,'reading','Which statement about languages in the National Assembly for Wales is correct?',array['Members may speak in Welsh or English, and publications are in both','Only English may be used for official publications','Members must speak Welsh to be elected','Only Welsh may be spoken in debates']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Members can use either language and all the Assembly''s publications are bilingual.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-029','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, in how many areas does the Welsh Assembly have power to make laws?',array['5','20','10','50']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The handbook says the Assembly can legislate in 20 areas, such as education, health and housing.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-030','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is an area in which the National Assembly for Wales can make laws?',array['Housing','Immigration','Defence','Foreign affairs']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Welsh Assembly''s law-making areas include housing, health, education and economic development.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-031','LIFE_IN_UK'::public.cefr_level,'reading','Since which year has the National Assembly for Wales been able to pass laws on its devolved topics without the UK Parliament''s agreement?',array['2007','2011','1997','1999']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): From 2011 the Assembly could legislate on these topics without UK Parliament agreement.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-032','LIFE_IN_UK'::public.cefr_level,'reading','How many members does the Scottish Parliament have?',array['129','60','90','650']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): There are 129 MSPs, elected by a form of proportional representation.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-033','LIFE_IN_UK'::public.cefr_level,'reading','On which matters can the Scottish Parliament pass laws?',array['Only matters approved by the House of Lords','Defence and foreign affairs only','All matters not specifically reserved to the UK Parliament','Only education and health']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The Scottish Parliament can legislate on anything not reserved to Westminster.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-034','LIFE_IN_UK'::public.cefr_level,'reading','Which of these can the Scottish Parliament legislate on?',array['Foreign affairs','Immigration','Civil and criminal law','Defence']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Matters for the Scottish Parliament include civil and criminal law, health, education, planning and additional tax-raising powers.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-036','LIFE_IN_UK'::public.cefr_level,'reading','The Northern Ireland Assembly was established soon after which agreement?',array['The Anglo-Irish Treaty of 1921','The Belfast (Good Friday) Agreement of 1998','The Act of Union of 1707','The Treaty of Rome of 1957']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Assembly followed the 1998 Belfast Agreement and shares ministerial offices among the main parties.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-037','LIFE_IN_UK'::public.cefr_level,'reading','What does the power-sharing agreement in the Northern Ireland Assembly do?',array['Shares seats equally with the Irish Parliament','Gives all power to the largest party','Lets the UK Parliament appoint every minister','Distributes ministerial offices among the main parties']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Ministerial offices are distributed among the main parties under power-sharing.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-038','LIFE_IN_UK'::public.cefr_level,'reading','How many elected members does the Northern Ireland Assembly have?',array['90','129','60','108']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Assembly has 90 MLAs elected by a form of proportional representation.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-039','LIFE_IN_UK'::public.cefr_level,'reading','What are members of the Northern Ireland Assembly called?',array['MLAs (Members of the Legislative Assembly)','MEPs','MSPs','AMs']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Northern Ireland Assembly members are known as MLAs.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-040','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is an issue the Northern Ireland Assembly can make decisions on?',array['Foreign affairs','Immigration','Defence','Agriculture']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The Assembly decides on matters such as education, agriculture, the environment, health and social services.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-041','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The UK government can suspend any of the devolved assemblies.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The UK government can suspend devolved assemblies and has done so several times in Northern Ireland.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-042','LIFE_IN_UK'::public.cefr_level,'reading','What does it mean that the UK has a free press?',array['The government owns all newspapers','Newspapers are given away free of charge','Newspapers are not controlled by the government','Newspapers may only report on sport']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): A free press means newspapers are not controlled by the government.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-043','LIFE_IN_UK'::public.cefr_level,'reading','What does the law require of radio and television coverage of political parties?',array['It must be balanced, giving equal time to rival viewpoints','It must support the governing party','It must be approved by the Prime Minister','It is banned during election campaigns']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Broadcast coverage of parties must by law be balanced.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-044','LIFE_IN_UK'::public.cefr_level,'reading','How can you find out which local authority you come under for voter registration?',array['Ask your local police station','Visit www.aboutmyvote.co.uk and enter your postcode','Phone HM Revenue & Customs','Write to the Speaker of the House']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The aboutmyvote website identifies your local authority from your postcode.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-045','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, when is the electoral register updated each year?',array['In May','In January','In July','In September or October']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The handbook says the register is updated annually in September or October, using a form sent to every household.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-046','LIFE_IN_UK'::public.cefr_level,'reading','What is the voter registration system used in Northern Ireland called?',array['Individual registration','Automatic registration','Postal registration','Household registration']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): In Northern Ireland every person entitled to vote completes their own form.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-047','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Each local authority must, by law, make its electoral register available for anyone to look at, under supervision.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Anyone may inspect the register under supervision at the electoral registration office or some public buildings such as libraries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-048','LIFE_IN_UK'::public.cefr_level,'reading','What does the poll card you are sent before an election tell you?',array['How much tax you owe','Which candidate you must vote for','Your National Insurance number','Where your polling station is and when the election takes place']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The poll card shows the location of your polling station or place and the election date.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-049','LIFE_IN_UK'::public.cefr_level,'reading','During what hours are polling stations open on election day?',array['9.00 am to 5.00 pm','8.00 am to 6.00 pm','7.00 am to 10.00 pm','6.00 am to midnight']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Polling stations and places open from 7 am until 10 pm.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-050','LIFE_IN_UK'::public.cefr_level,'reading','What are polling stations called in Scotland?',array['Voting halls','Polling places','Election points','Ballot rooms']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): In Scotland the term used is polling places.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-051','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, in which part of the UK must voters also show photographic identification at the polling station?',array['Scotland','Wales','London only','Northern Ireland']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The handbook states that photo ID is required in Northern Ireland.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-052','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Nobody is entitled to force you to vote for a certain candidate.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): You fill in your ballot privately and should decide for yourself whom to vote for.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-053','LIFE_IN_UK'::public.cefr_level,'reading','If it is difficult to get to a polling station, how else can you vote?',array['By telephoning the council on election day','By emailing your vote to your MP','By registering for a postal ballot','By asking a police officer to vote for you']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): With a postal ballot your ballot paper is sent to your home and you post it back.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-054','LIFE_IN_UK'::public.cefr_level,'reading','Which of these groups cannot stand for public office?',array['Shop owners','Farmers','Members of the armed forces','Taxi drivers']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Exceptions include members of the armed forces, civil servants and people guilty of certain criminal offences.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-055','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Members of the House of Lords may stand for election to the House of Commons.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Peers cannot stand for the House of Commons, though they may stand for every other public office.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-056','LIFE_IN_UK'::public.cefr_level,'reading','Which is usually easier for visitors to get into?',array['Neither is open to visitors','The House of Commons','Both are equally difficult','The House of Lords']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Queues for the Commons can be long, but it is usually easier to get into the Lords.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-057','LIFE_IN_UK'::public.cefr_level,'reading','How can you get tickets to watch debates at the Palace of Westminster?',array['Ask the Prime Minister''s office','Buy them from a ticket agency','Apply to the monarch','Write to your local MP in advance or queue on the day']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): You can request tickets from your MP or queue at the public entrance; entry is free.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-058','LIFE_IN_UK'::public.cefr_level,'reading','What is the name of the place in Belfast where the Northern Ireland Assembly meets?',array['Stormont','Westminster','Holyrood','The Senedd']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): MLAs meet in the Northern Ireland Assembly at Stormont in Belfast.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-059','LIFE_IN_UK'::public.cefr_level,'reading','Where in Edinburgh is the Scottish Parliament building?',array['Holyrood','Cardiff Bay','Stormont','Calton Hill']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): MSPs meet in the Scottish Parliament building at Holyrood.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.6-060','LIFE_IN_UK'::public.cefr_level,'reading','In which building do Welsh Assembly members meet?',array['Holyrood in Edinburgh','The Senedd in Cardiff Bay','Westminster Hall in London','Stormont in Belfast']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): The Welsh Assembly meets in the Senedd, an open building in Cardiff Bay.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-001','LIFE_IN_UK'::public.cefr_level,'reading','On which core values is the Commonwealth based?',array['A common religion and a common language','Free trade, a single currency and open borders','Military defence and shared armed forces','Democracy, good government and the rule of law']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Commonwealth members work together on democracy and development, based on democracy, good government and the rule of law.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-002','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Commonwealth has the power to suspend a country''s membership.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Commonwealth has no power over its members but can suspend membership.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-003','LIFE_IN_UK'::public.cefr_level,'reading','Who is the ceremonial head of the Commonwealth?',array['The Prime Minister','The President of the Council of Europe','The Secretary-General of the United Nations','The monarch']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The monarch is the Commonwealth''s ceremonial head.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-004','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Every member of the Commonwealth was once part of the British Empire.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Most members were once in the British Empire, but a few countries that were not have also joined.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-005','LIFE_IN_UK'::public.cefr_level,'reading','Which of these European countries is a member of the Commonwealth?',array['France','Spain','Greece','Malta']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The European members listed are Cyprus, Malta and the United Kingdom.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-006','LIFE_IN_UK'::public.cefr_level,'reading','Which of these Asian countries is a member of the Commonwealth?',array['Bangladesh','Thailand','Japan','China']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Asian members include Bangladesh, India, Malaysia, Pakistan, Singapore and Sri Lanka.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-007','LIFE_IN_UK'::public.cefr_level,'reading','What is the Council of Europe responsible for?',array['Protecting and promoting human rights in its member countries','Organising the European football championship','Running a single European currency','Commanding a joint European army']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Council of Europe, separate from the EU, protects and promotes human rights.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-008','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, how many member countries does the Council of Europe have?',array['27','54','15','47']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The handbook says the Council of Europe has 47 members, including the UK.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-009','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: The Council of Europe has the power to make laws for its member countries.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): It cannot make laws but draws up conventions and charters, such as the European Convention on Human Rights.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-010','LIFE_IN_UK'::public.cefr_level,'reading','About how many countries are members of the United Nations?',array['More than 190','About 50','Exactly 150','About 100']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The UN is an international organisation with over 190 member countries.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-011','LIFE_IN_UK'::public.cefr_level,'reading','When was the United Nations set up?',array['After the Second World War','In 1973','In the 19th century','After the First World War']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The UN was created after the Second World War to prevent war and promote peace and security.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-012','LIFE_IN_UK'::public.cefr_level,'reading','How many members are there on the UN Security Council?',array['10','5','15','27']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The Security Council has 15 members, five of them permanent, including the UK.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-013','LIFE_IN_UK'::public.cefr_level,'reading','What does the UN Security Council do?',array['Recommends action during international crises and threats to peace','Runs the UK''s armed forces','Sets taxes for member countries','Elects the UK Prime Minister']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): The Security Council recommends action when there are crises or threats to peace.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.7-014','LIFE_IN_UK'::public.cefr_level,'reading','What is NATO?',array['A UN agency for refugees','An alliance of European and North American countries pledged to help one another if attacked','A European court of human rights','A trade association of former British colonies']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): NATO members agree to help one another if attacked and aim to keep peace among themselves.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-001','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the shared values and responsibilities listed for everyone in the UK?',array['To attend a place of worship','To vote in local and national government elections','To join a political party','To live in the same area for life']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Shared responsibilities include obeying the law, helping others and voting in local and national elections.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-002','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Respecting and preserving the environment is listed as one of the shared responsibilities of people in the UK.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Looking after the environment is among the shared values and responsibilities.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-003','LIFE_IN_UK'::public.cefr_level,'reading','What does the handbook suggest you do when you move into a new home?',array['Register with the local police','Write to your MP','Introduce yourself to your neighbours','Hold a street party']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Getting to know neighbours helps you become part of the community and make friends.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-004','LIFE_IN_UK'::public.cefr_level,'reading','Which of these helps prevent problems with your neighbours?',array['Respecting their privacy and limiting noise','Leaving rubbish bags on the street at all times','Playing loud music late at night','Parking across their driveway']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Respect neighbours'' privacy, keep noise down and keep your garden tidy.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-005','LIFE_IN_UK'::public.cefr_level,'reading','When should rubbish bags and bins be put out on the street?',array['Only when they are due to be collected','At any time, day or night','Whenever they are full','Once a month, on the first day']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Bins and rubbish bags should go out only when due for collection.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-006','LIFE_IN_UK'::public.cefr_level,'reading','According to the handbook, people on the electoral register within which age range can be selected for jury service?',array['25 to 80','21 to 60','16 to 65','18 to 70']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): The handbook says anyone on the register aged 18 to 70 can be asked to serve on a jury.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-007','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one way parents can help in their children''s school?',array['Writing the national curriculum','Marking national exam papers','Listening to children read','Setting the school''s teachers'' pay']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Parents can help in classrooms, support activities or listen to children read.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-008','LIFE_IN_UK'::public.cefr_level,'reading','What do the letters PTA stand for?',array['Public teaching agency','Primary tuition allowance','Pupil training authority','Parent-teacher association']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): School events are sometimes organised by parent-teacher associations.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-009','LIFE_IN_UK'::public.cefr_level,'reading','What are school governors called in Scotland?',array['Trustees of the kirk','Members of the school board','Sheriffs of education','Members of the Children''s Panel']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): In Scotland the equivalent of school governors are members of the school board.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-010','LIFE_IN_UK'::public.cefr_level,'reading','What is the age requirement for becoming a school governor?',array['21 or over, up to age 65','18 or over, with no upper age limit','25 or over, up to age 70','Any age, if a parent of a pupil']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Governors must be 18 or older when elected or appointed, with no upper age limit.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-011','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is one of the three key roles of school governors?',array['Writing exam papers','Recruiting pupils from abroad','Ensuring accountability','Inspecting police records']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Governors set the school''s strategic direction, ensure accountability and monitor performance.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-012','LIFE_IN_UK'::public.cefr_level,'reading','In England, who may apply to set up a free school locally?',array['Parents and other community groups','Only universities','Only local councils','Only the Church of England']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Parents, as well as other community groups, may apply to set up a free school in England.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-013','LIFE_IN_UK'::public.cefr_level,'reading','What is ''canvassing''?',array['Painting election posters','Party members asking people for their support, for example by knocking on doors','Registering people on the electoral roll','Counting votes after an election']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Canvassing means persuading people to vote for a party''s candidates, by leafleting or door-knocking.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-014','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: You must tell a canvasser how you intend to vote.',array['True','False']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): You do not have to tell a canvasser how you will vote if you do not want to.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-015','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is a way to volunteer with the police?',array['Becoming a District Judge','Becoming a special constable','Becoming a Chief Constable','Becoming a Police and Crime Commissioner']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): You can volunteer as a special constable or a lay (non-police) representative.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-016','LIFE_IN_UK'::public.cefr_level,'reading','Which of these local bodies may advertise for volunteers to serve on their governing bodies?',array['Housing associations','The House of Lords','HM Revenue & Customs','The Crown Court']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Universities, housing associations, museums and arts councils may seek volunteers for their governing bodies.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-017','LIFE_IN_UK'::public.cefr_level,'reading','About how long does it take to give blood?',array['About half a day','About two days','About an hour','About ten minutes']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Giving blood takes only around an hour.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-018','LIFE_IN_UK'::public.cefr_level,'reading','How can registering as an organ donor help?',array['It gives you priority for NHS treatment','It exempts you from jury service','It can help your family decide whether to donate your organs after your death','It reduces your income tax']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Registering helps your family decide on organ donation after your death.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-019','LIFE_IN_UK'::public.cefr_level,'reading','TRUE or FALSE: Living people can donate a kidney.',array['True','False']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Besides donation after death, living people can donate a kidney.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-020','LIFE_IN_UK'::public.cefr_level,'reading','What is volunteering?',array['Working for the government on a fixed contract','Working for good causes without payment','Working abroad for an international company','Doing compulsory community service ordered by a court']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Volunteering means unpaid work for good causes.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-021','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is given as a benefit of volunteering?',array['A chance to practise English or develop work skills','A guaranteed government job','Automatic British citizenship','Exemption from income tax']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Volunteering can help you practise English, gain work skills and improve your CV.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-022','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is given as an example of mentoring as a volunteer?',array['Supporting someone who has just come out of prison','Working on a hospital information desk','Caring for animals at a rescue shelter','Joining a litter pick-up']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Mentoring, such as supporting someone recently released from prison, is one volunteering activity.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-023','LIFE_IN_UK'::public.cefr_level,'reading','Which charity works with children?',array['Crisis','Age UK','The National Society for the Prevention of Cruelty to Children (NSPCC)','Cancer Research UK']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The NSPCC is given as an example of a charity working with children.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-024','LIFE_IN_UK'::public.cefr_level,'reading','Which charity works with older people?',array['The NSPCC','Age UK','The PDSA','Shelter']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Age UK is named as a charity working with older people.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-025','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO charities are given as examples of organisations working with homeless people?',array['Age UK and the NSPCC','Cancer Research UK and the PDSA','Friends of the Earth and the British Red Cross','Crisis and Shelter']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Crisis and Shelter are the examples of charities for the homeless.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-026','LIFE_IN_UK'::public.cefr_level,'reading','What kind of charity is the People''s Dispensary for Sick Animals (PDSA)?',array['A charity for homeless people','An environmental charity','A charity working with animals','A medical research charity']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The PDSA is named as an animal charity.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-027','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is given as an example of a medical research charity?',array['Friends of the Earth','The NSPCC','Cancer Research UK','Shelter']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): Cancer Research UK is the example of a medical research charity.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-028','LIFE_IN_UK'::public.cefr_level,'reading','Which TWO are given as examples of environmental charities?',array['The NSPCC and Shelter','Cancer Research UK and the PDSA','Age UK and Crisis','The National Trust and Friends of the Earth']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Environmental charities named include the National Trust and Friends of the Earth.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-029','LIFE_IN_UK'::public.cefr_level,'reading','The British Red Cross is given as an example of what?',array['A British branch of an international organisation','A government department','A pressure group for business','A political party']::text[],'A','Handbook ch. 5 (The UK government, the law and your role): Charities range from British branches of international bodies like the Red Cross to small local charities.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-030','LIFE_IN_UK'::public.cefr_level,'reading','Which programme gives 16- and 17-year-olds the chance to do outdoor activities, develop skills and take part in a community project?',array['The Children''s Hearings System','The Youth Training Scheme','National Citizen Service','Youth conferencing']::text[],'C','Handbook ch. 5 (The UK government, the law and your role): The National Citizen Service is for young people aged 16 and 17.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-031','LIFE_IN_UK'::public.cefr_level,'reading','Why does using recycled materials to make new products help the environment?',array['It makes products more expensive, so people buy less','It uses less energy and reduces the need to extract raw materials','It means factories can work longer hours','It increases the amount of rubbish sent to landfill']::text[],'B','Handbook ch. 5 (The UK government, the law and your role): Recycling saves energy, means fewer raw materials are taken from the earth and reduces landfill.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice'),
  ('lituk:S5.8-032','LIFE_IN_UK'::public.cefr_level,'reading','Which of these is a benefit of shopping for products locally?',array['It means you pay no VAT','It increases the amount of packaging used','It entitles you to vote in local elections','It helps local businesses and farmers and reduces your carbon footprint']::text[],'D','Handbook ch. 5 (The UK government, the law and your role): Buying locally supports local businesses and farmers and cuts the distance products travel.',array['life_in_uk','lituk_government']::text[],'draft','unreviewed','ai-draft:ai-batch-05',null,null,null,null,'practice')
